def max_average_power(n, k, m, a):
    a.sort()
    operations = m
    for i in range(n-1):
        if operations >= k:
            a[i] += k
            operations -= k
        else:
            break
    while operations > 0 and len(a) > 1:
        a.pop(0)
        operations -= 1
    return sum(a) / len(a)

