import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
k = int(data[1])
m = int(data[2])

powers = list(map(int, data[3:]))

def can_increase(powers, target):
    operations = 0
    for i in range(n):
        if powers[i] < target:
            operations += max(0, target - powers[i], k)
            if operations > m:
                return False
    return True

def can_remove(powers, target):
    operations = 0
    for i in range(n):
        if powers[i] > target:
            operations += powers[i] - target
            if operations > m:
                return False
    return True

left, right = min(powers), max(powers)
while left + 1e-9 < right:
    mid = (left + right) / 2
    if can_increase(powers, mid) or can_remove(powers, mid):
        left = mid
    else:
        right = mid

print(left)
